import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    n = int(data[0])

    a = []
    for i in range(n):
        a.append(int(data[1 + i]))

    b = []
    for i in range(n):
        b.append(int(data[1 + n + i]))

    # Identify students who can be part of a valid group.
    # A student i can be in a valid group if there exists some student j such that
    # (a_i | a_j) == a_j. This means the set of algorithms known by i is a subset of those known by j.
    # If a student satisfies this, they can be included in a group with j (and potentially others).
    # The maximal elements (those not subsets of any other) will satisfy this condition with themselves.

    dominated = [False] * n

    for i in range(n):
        for j in range(n):
            # Check if a_i is a subset of a_j
            if (a[i] | a[j]) == a[j]:
                dominated[i] = True
                break

    # Calculate the sum of b_i for all dominated students
    total_skill = 0
    count = 0
    for i in range(n):
        if dominated[i]:
            total_skill += b[i]
            count += 1

    # The problem requires a group of at least two students.
    if count >= 2:
        print(total_skill)
    else:
        print(0)

if __name__ == "__main__":
    solve()
